What will be the output of the following C code?

int arr[] = {10, 20, 30, 40, 50};
int *p = arr;
printf("%d", *(p + 2) + p[1]);

What is the output of the following C program?

void swap(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
}

int main() {
    int x = 5, y = 10;
    swap(x, y);
    printf("%d %d", x, y);
    return 0;
}

What will the following code print?

int arr[] = {1, 2, 3, 4, 5};
int *p = arr;
printf("%d", *(arr + 3) - *(p + 1));

What is the value of `res` after the following code executes?

int arr[] = {1, 3, 5, 7, 9};
int *p = arr;
int res = 0;
for (int i = 0; i < 4; i++) {
    res += *(p + i) * i;
}
